// Load fake-ts.hdf5, exported by `aida-data export fake-ts`.
// Generated by aida-data 0.0.0 for HighFive 3.x (H5Easy), tested with HighFive 3.3.0.
// It loads the objects of the file it was generated from; each comment gives the shape and dtype.
//
// Build: h5c++ -std=c++17 -I/path/to/highfive/include load.cpp -o load
// or with CMake:
//   find_package(HighFive REQUIRED)
//   target_link_libraries(load HighFive::HighFive)
// HighFive comes from a package manager (apt install libhighfive-dev,
// conda install highfive, vcpkg install highfive) or a git submodule.
// With HighFive 2.x the CMake target is `HighFive` and DataSet::read_raw(T*)
// is DataSet::read(T*).
#include <highfive/H5Easy.hpp>

#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

int main() {
    H5Easy::File file("fake-ts.hdf5", H5Easy::File::ReadOnly);

    // (10, 2) float64, one row per time step, one column per dimension.
    auto values = H5Easy::load<std::vector<std::vector<double>>>(file, "/values");

    // (10,) int64, milliseconds since the Unix epoch, one per row of values.
    auto time = H5Easy::load<std::vector<int64_t>>(file, "/time");

    // Name of each column of values.
    auto dim_names = H5Easy::loadAttribute<std::vector<std::string>>(file, "/", "dim_names");

    // Sampling period of the series, e.g. 1s.
    auto sampling = H5Easy::loadAttribute<std::string>(file, "/", "sampling");

    // URL of the data, several are separated by spaces.
    auto source = H5Easy::loadAttribute<std::string>(file, "/", "source");

    // For large data, read into one contiguous row-major buffer instead:
    //   HighFive::DataSet ds = file.getDataSet("/values");
    //   auto dims = ds.getDimensions();
    //   std::vector<double> flat(dims[0] * dims[1]);
    //   ds.read_raw(flat.data());
    // or, with H5_USE_EIGEN defined before including HighFive:
    //   using Matrix = Eigen::Matrix<double, Eigen::Dynamic, Eigen::Dynamic,
    //                                Eigen::RowMajor>;
    //   auto m = H5Easy::load<Matrix>(file, "/values");

    // The shapes of what was loaded.
    std::cout << "values: " << values.size() << " x " << (values.empty() ? 0 : values[0].size()) << "\n";
    std::cout << "time: " << time.size() << "\n";
    std::cout << "dim_names: " << dim_names.size() << "\n";
    std::cout << "sampling: " << sampling << "\n";
    std::cout << "source: " << source << "\n";
}
